"""Service latency SLO report (see README.md)."""
from __future__ import annotations

import math

SLO_P95_MS = 300.0


def p95(values):
    """Nearest-rank 95th percentile."""
    s = sorted(values)
    return s[max(0, math.ceil(0.95 * len(s)) - 1)]


def compute(records):
    """p95 latency per service (ms, 1 decimal) and which services breach the 300 ms SLO."""
    by = {}
    for r in records:
        by.setdefault(r["service"], []).append(r["latency_ms"])
    p = {k: round(p95(v), 1) for k, v in sorted(by.items())}
    return {"p95_ms": p, "slo_breaches": sorted(k for k, v in p.items() if v > SLO_P95_MS),
            "worst_service": max(p, key=p.get)}

"""Integration tests for reports/slo.json."""
import json
from pathlib import Path

import pytest

from scripts.build_report import load_records
from src.metrics import compute

ROOT = Path(__file__).resolve().parents[1]
REPORT = ROOT / "reports/slo.json"
ENTITIES = ['auth', 'checkout', 'payments', 'search']


@pytest.fixture(scope="module")
def report():
    assert REPORT.exists(), "report not built; run scripts/build_report.py"
    return json.loads(REPORT.read_text())


def test_all_services_present(report):
    assert report["services"] == ENTITIES


def test_report_matches_raw_data(report):
    expected = compute(load_records())
    for key, value in expected.items():
        assert report[key] == value, key

